'use strict';
const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict'),{createHash}=require('node:crypto');
module.exports=repo=>{const sha=b=>createHash('sha256').update(b).digest('hex'),base='.artifacts/deep-audit-round2-fixes-acceptance/',load=p=>JSON.parse(fs.readFileSync(path.join(repo,p)));
const mapping=load(base+'review-rejected-v1/mapping.json'),mapped=new Map(mapping.files.filter(f=>f.willModify).map(f=>[f.originalPath,f]));
const prior=load(base+'final-freeze.json'),v2=load(base+'final-freeze-v2.json'),baseline=load(base+'baseline.json');
const records=[];function check(record,kind,remap=false){const original=record.path??record.originalPath,target=remap&&mapped.has(original)?mapped.get(original).savedPath:original;assert.ok(!path.isAbsolute(target)&&!target.split('/').includes('..'));const b=fs.readFileSync(path.join(repo,target));assert.equal(sha(b),record.sha256,kind+': '+original);if(record.bytes!==undefined)assert.equal(b.length,record.bytes);records.push({kind,path:original,resolved:target,sha256:sha(b),bytes:b.length});}
assert.equal(sha(fs.readFileSync(path.join(repo,base+'final-freeze.json'))),'0a177daaa181f7c7829279113cc1a46d4614ccea507ff474dc55258903918208');assert.equal(sha(fs.readFileSync(path.join(repo,base+'final-freeze-v2.json'))),'62f41c0c1c1f863c7cec76c0e9865ede16b28f76578e2f51e1cc86fb66719512');
for(const record of prior.files)check(record,'prior-v1',true);for(const record of v2.files)check(record,'accepted-v2');for(const record of baseline.frozen)check(record,'history-638');
const masterPath='docs/deep-audit/coverage-master.json';assert.equal(sha(fs.readFileSync(path.join(repo,masterPath))),'8d5cad11503953cb9044a96902ab92d718cb21ae17107313549c5e45fb527794');const summary=load(masterPath).summary;assert.equal(summary.userOperations,115);assert.equal(summary.independentlyAccepted,104);assert.equal(summary.domainFindingRows,598);
return{counts:{prior:prior.files.length,v2:v2.files.length,historical:baseline.frozen.length,mapped:mapped.size},records,summary:{userOperations:summary.userOperations,independentlyAccepted:summary.independentlyAccepted,domainFindingRows:summary.domainFindingRows},drift:0};};
